        "content": "{\"entries\":[{\"id\":\"R-0001\",\"proposition\":\"Das Kundenportal soll als Web-Portal realisiert werden, mobile Nutzung ist später geplant.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Frontend\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0001: Also wir brauchen definitiv ein Kundenportal. ... Web first. Mobile später.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"Mobile erst nach MVP\",\"sourceUnitIds\":[\"AU-0001\"]},{\"id\":\"R-0002\",\"proposition\":\"Das Backend ist aktuell nicht API-ready, daher wird eine API Layer benötigt, um Integration zu ermöglichen.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Backend\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0002: ... unser Backend noch nicht mal API-ready.\"},{\"source\":\"transcript\",\"quote\":\"AU-0036: Wir brauchen definitiv eine API Layer. Sonst können wir nichts integrieren.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"API Layer zwingend für Integration\",\"sourceUnitIds\":[\"AU-0002\",\"AU-0036\"]},{\"id\":\"C-0001\",\"proposition\":\"Das Kundenportal muss DSGVO-konform sein, inklusive Double-Opt-In, Löschkonzept, Audit Trails und Auftragsverarbeitungsverträgen.\",\"kind\":\"compliance_constraint\",\"status\":\"required\",\"modality\":\"must\",\"scope\":\"Compliance\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0003: DSGVO. ... Double-Opt-In. Und Logging. Und Löschkonzepte. Und Auftragsverarbeitungsverträge.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"not_applicable\",\"representationMode\":\"consciously_omitted\"}},\"riskLevel\":\"high\",\"notes\":\"DSGVO ist Pflicht\",\"sourceUnitIds\":[\"AU-0003\"]},{\"id\":\"R-0003\",\"proposition\":\"Login erfolgt per E-Mail und Passwort mit Double-Opt-In; SSO (Azure AD, Google) ist optional und noch nicht entschieden.\",\"kind\":\"requirement\",\"status\":\"open\",\"modality\":\"must_consider\",\"scope\":\"Authentication\",\"timeScope\":\"mvp_or_later_unclear\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0004: Also erstmal Login per E-Mail und Passwort. SSO wäre schön. Vielleicht Azure AD. Oder Google? Oder beides?\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"open-questions\":{\"applicability\":\"required\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"SSO noch offen\",\"sourceUnitIds\":[\"AU-0004\"]},{\"id\":\"R-0004\",\"proposition\":\"Rollenmodell mit mindestens Admin, Sales, Kunde; Support wird im MVP nicht berücksichtigt.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Authorization\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0066: Wir brauchen einen Architekten.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 4. Rollen Admin/Sales/Kunde\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"Support ausgeschlossen im MVP\",\"sourceUnitIds\":[\"AU-0066\",\"AU-0199\"]},{\"id\":\"R-0005\",\"proposition\":\"Angebote müssen mit SAP-Daten gelesen werden; SAP-Verfügbarkeit ist kritische Abhängigkeit.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Integration\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0199: 2. Angebotserstellung mit SAP-Lesedaten\"},{\"source\":\"transcript\",\"quote\":\"AU-0246: Bitte schreibt \\\"SAP-Verfügbarkeit ist kritische Abhängigkeit\\\".\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"SAP-Verfügbarkeit kritisch\",\"sourceUnitIds\":[\"AU-0199\",\"AU-0246\"]},{\"id\":\"R-0006\",\"proposition\":\"Rechnungsdownload soll im Kundenportal möglich sein.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Frontend\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0011: Kunden sollen Bestellungen sehen und Rechnungen downloaden.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 3. Rechnungsdownload\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"low\",\"notes\":\"Rechnungen im MVP\",\"sourceUnitIds\":[\"AU-0011\",\"AU-0199\"]},{\"id\":\"R-0007\",\"proposition\":\"Audit Trail mit minimalem Logging und Protokollierung der Änderungen ist erforderlich.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Security\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0023: Auditierbarkeit ist Pflicht.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 5. Minimaler Audit Trail\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Audit Trail minimal im MVP\",\"sourceUnitIds\":[\"AU-0023\",\"AU-0199\"]},{\"id\":\"R-0008\",\"proposition\":\"EU-only Managed Hosting ist erforderlich, um DSGVO-Konformität sicherzustellen.\",\"kind\":\"compliance_constraint\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Hosting\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0032: Ja EU only. Oder zumindest DSGVO-konform.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 6. EU Managed Hosting\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"EU-only Hosting verpflichtend\",\"sourceUnitIds\":[\"AU-0032\",\"AU-0199\"]},{\"id\":\"R-0009\",\"proposition\":\"Backup und Disaster Recovery sind für das MVP erforderlich.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Security\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0043: Ja Disaster Recovery.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 7. Backup\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Backup und DR im MVP\",\"sourceUnitIds\":[\"AU-0043\",\"AU-0199\"]},{\"id\":\"C-0002\",\"proposition\":\"Keine personenbezogenen Daten dürfen in technischen Logs gespeichert werden; Audit-Logs sind getrennt zu behandeln.\",\"kind\":\"compliance_constraint\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Logging\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0248: Und \\\"keine personenbezogenen Daten in technischen Logs\\\".\"},{\"source\":\"transcript\",\"quote\":\"AU-0180: ... zentrales Monitoring darf keine personenbezogenen Daten in Logs enthalten.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Trennung Audit- und technisches Logging\",\"sourceUnitIds\":[\"AU-0248\",\"AU-0180\"]},{\"id\":\"R-0010\",\"proposition\":\"OAuth wird als bevorzugtes API-Sicherheitsverfahren betrachtet, ist aber noch nicht final entschieden.\",\"kind\":\"open_question\",\"status\":\"open\",\"modality\":\"must_consider\",\"scope\":\"Security\",\"timeScope\":\"mvp_or_later_unclear\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0258: Und OAuth ist bevorzugt, aber noch nicht final.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"open-questions\":{\"applicability\":\"required\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"OAuth noch offen\",\"sourceUnitIds\":[\"AU-0258\"]},{\"id\":\"R-0011\",\"proposition\":\"Im MVP dürfen keine manuellen Sonderrabatte über dem Standardsatz erstellt werden.\",\"kind\":\"constraint\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Business Rules\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0203: Das wäre eine Constraint: keine manuellen Sonderrabatte im MVP.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"constraint\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Rabatt-Freigabe im MVP ausgeschlossen\",\"sourceUnitIds\":[\"AU-0203\"]},{\"id\":\"R-0012\",\"proposition\":\"Support wird im MVP nur über ein Kontaktformular ohne Ticketpersistenz realisiert; dies stellt ein Risiko dar.\",\"kind\":\"risk\",\"status\":\"open\",\"modality\":\"must_note\",\"scope\":\"Support\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0206: Kontaktformular ohne Ticketpersistenz?\"},{\"source\":\"transcript\",\"quote\":\"AU-0211: Notieren als Risiko.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Support ohne Ticketsystem als Risiko\",\"sourceUnitIds\":[\"AU-0206\",\"AU-0211\"]},{\"id\":\"R-0013\",\"proposition\":\"MVP umfasst Login mit Double-Opt-In, Angebotserstellung mit SAP-Lesedaten, Rechnungsdownload, Rollen Admin/Sales/Kunde, minimalen Audit Trail, EU Managed Hosting und Backup.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"MVP\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0199: MVP: 1. Login mit Double-Opt-In 2. Angebotserstellung mit SAP-Lesedaten 3. Rechnungsdownload 4. Rollen Admin/Sales/Kunde 5. Minimaler Audit Trail 6. EU Managed Hosting 7. Backup\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Klares MVP-Scope\",\"sourceUnitIds\":[\"AU-0199\"]},{\"id\":\"R-0014\",\"proposition\":\"API Gateway ist Pflicht laut interner Policy, aber das Gateway-Team hat eine sechs Wochen Warteliste, was das 8-Wochen-MVP gefährdet.\",\"kind\":\"constraint\",\"status\":\"open\",\"modality\":\"must_note\",\"scope\":\"Architecture\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0110: interne Policy, dass neue externe Portale über das zentrale API Gateway laufen müssen.\"},{\"source\":\"transcript\",\"quote\":\"AU-0111: Gateway-Team hat gerade eine Warteliste von sechs Wochen.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"required\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"API Gateway Warteliste als Risiko\",\"sourceUnitIds\":[\"AU-0110\",\"AU-0111\"]},{\"id\":\"R-0015\",\"proposition\":\"Angebote müssen revisionssicher nachvollziehbar sein mit Versionierung der Templates und Audit-Logs.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Compliance\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0163: Templates müssen versioniert werden.\"},{\"source\":\"transcript\",\"quote\":\"AU-0164: Angebote müssen revisionssicher nachvollziehbar sein.\"},{\"source\":\"transcript\",\"quote\":\"AU-0166: Dann brauchen wir Event-History oder Audit-Log pro Angebot.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Revisionssicherheit für Angebote\",\"sourceUnitIds\":[\"AU-0163\",\"AU-0164\",\"AU-0166\"]},{\"id\":\"R-0016\",\"proposition\":\"Supportprozess ist unklar und muss noch definiert werden.\",\"kind\":\"open_question\",\"status\":\"open\",\"modality\":\"must_clarify\",\"scope\":\"Support\",\"timeScope\":\"mvp_or_later_unclear\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0251: Und \\\"Supportprozess unklar\\\".\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"question\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"question\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"question\"},\"open-questions\":{\"applicability\":\"required\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"Supportprozess offen\",\"sourceUnitIds\":[\"AU-0251\"]},{\"id\":\"R-0017\",\"proposition\":\"Es besteht ein Berechtigungskonflikt zwischen Support-Zugriffsrechten und Datenschutz bei Angeboten, der modelliert und protokolliert werden muss.\",\"kind\":\"risk\",\"status\":\"open\",\"modality\":\"must_consider\",\"scope\":\"Authorization\",\"timeScope\":\"mvp_or_later_unclear\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0095: Das ist ein klassischer Berechtigungskonflikt. Müssen wir modellieren.\"},{\"source\":\"transcript\",\"quote\":\"AU-0096: Und protokollieren. Wer hat welches Angebot geöffnet?\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Berechtigungskonflikt Support\",\"sourceUnitIds\":[\"AU-0095\",\"AU-0096\"]},{\"id\":\"R-0018\",\"proposition\":\"Kostenschätzung für Vorstand bis Freitag wird benötigt, obwohl Architekturentscheidungen noch offen sind.\",\"kind\":\"open_requirement\",\"status\":\"open\",\"modality\":\"must_note\",\"scope\":\"Project Management\",\"timeScope\":\"mvp_or_later_unclear\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0103: Wir brauchen aber eine Kostenschätzung für den Vorstand bis Freitag.\"},{\"source\":\"transcript\",\"quote\":\"AU-0104: Wir haben nicht mal eine Architekturentscheidung.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"required\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Kostenschätzung mit unklarer Architektur\",\"sourceUnitIds\":[\"AU-0103\",\"AU-0104\"]},{\"id\":\"R-0019\",\"proposition\":\"MVP-Scope muss klar definieren, was enthalten ist, was bewusst ausgeschlossen wird und welche Risiken dadurch entstehen.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Project Management\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0262: Dann ist das finale Ziel für jetzt: ein MVP-Schnitt, der klar sagt, was drin ist, was bewusst ausgeschlossen ist und welche Risiken dadurch entstehen.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"Klares MVP-Scope und Risiko-Transparenz\",\"sourceUnitIds\":[\"AU-0262\"]}]}"
