    {
      "id": "AU-0056",
      "speaker": "Ben",
      "text": "Und Portal."
    },
    {
      "id": "AU-0057",
      "speaker": "Clara",
      "text": "Und Compliance."
    },
    {
      "id": "AU-0059",
      "speaker": "Ben",
      "text": "Was ist mit Support? Ticketsystem?"
    },
    {
      "id": "AU-0060",
      "speaker": "Anna",
      "text": "Nein erstmal nicht."
    },
    {
      "id": "AU-0061",
      "speaker": "Clara",
      "text": "Aber wenn ein Kunde seine Daten l\u00F6schen will?"
    },
    {
      "id": "AU-0062",
      "speaker": "Anna",
      "text": "Dann muss das gehen."
    },
